import random

# সহজ 1D Regression Dataset (X থেকে y predict করছি)
X = [1, 2, 3, 4, 5, 6]
y = [3.0, 5.0, 7.0, 15.0, 18.0, 20.0]


def mean_value(vals):
    total = 0.0
    for v in vals:
        total += v
    return total / len(vals)


def fit_stump(X_sub, y_sub):
    unique_x = sorted(set(X_sub))
    if len(unique_x) < 2:
        return {"is_leaf": True, "val": mean_value(y_sub)}

    best_sse = None
    best = None
    for k in range(len(unique_x) - 1):
        th = (unique_x[k] + unique_x[k + 1]) / 2.0
        left_y = []
        right_y = []
        for i in range(len(X_sub)):
            if X_sub[i] <= th:
                left_y.append(y_sub[i])
            else:
                right_y.append(y_sub[i])
        if len(left_y) == 0 or len(right_y) == 0:
            continue
        l_mean = mean_value(left_y)
        r_mean = mean_value(right_y)
        sse = 0.0
        for v in left_y:
            sse += (v - l_mean) ** 2
        for v in right_y:
            sse += (v - r_mean) ** 2
        if best_sse is None or sse < best_sse:
            best_sse = sse
            best = {"is_leaf": False, "th": th, "left": l_mean, "right": r_mean}
    return best


def predict_stump(stump, x_val):
    if stump["is_leaf"]:
        return stump["val"]
    if x_val <= stump["th"]:
        return stump["left"]
    return stump["right"]


# --- Bagging Training: B=10টি স্বাধীন Bootstrap Stump ---
random.seed(42)
B = 10
bag_trees = []
for b in range(B):
    X_boot = []
    y_boot = []
    for step in range(len(X)):
        idx = random.randrange(len(X))
        X_boot.append(X[idx])
        y_boot.append(y[idx])
    bag_trees.append(fit_stump(X_boot, y_boot))

# --- Inference: সব B-টি Tree-এর Prediction-এর গড়! ---
X_new = [2.5, 3.5, 4.5]
for x_val in X_new:
    preds = []
    for tree in bag_trees:
        preds.append(predict_stump(tree, x_val))
    print(f"x={x_val} -> Bagging mean pred = {mean_value(preds):.4f}")

import random

# ৩টি Feature: [feature_0 (অতি শক্তিশালী), feature_1 (ভালো), feature_2 (ভালো)]
X = [
    [1, 1, 2], [1, 2, 1], [2, 1, 2], [2, 2, 1],
    [8, 7, 8], [8, 8, 7], [9, 7, 9], [9, 9, 8],
]
y = [0, 0, 0, 0, 1, 1, 1, 1]


def gini_impurity(labels):
    if len(labels) == 0:
        return 0.0
    ones = 0
    for v in labels:
        ones += v
    p1 = ones / len(labels)
    p0 = 1.0 - p1
    return 1.0 - (p0 * p0 + p1 * p1)


def best_split_on_subset(X_data, y_data, allowed_features):
    best_score = None
    best_choice = None
    n = len(X_data)
    for f in allowed_features:
        col_vals = []
        for row in X_data:
            col_vals.append(row[f])
        unique_v = sorted(set(col_vals))
        for k in range(len(unique_v) - 1):
            th = (unique_v[k] + unique_v[k + 1]) / 2.0
            left_y = []
            right_y = []
            for i in range(n):
                if X_data[i][f] <= th:
                    left_y.append(y_data[i])
                else:
                    right_y.append(y_data[i])
            if len(left_y) == 0 or len(right_y) == 0:
                continue
            weighted_gini = (len(left_y) / n) * gini_impurity(left_y) + (len(right_y) / n) * gini_impurity(right_y)
            if best_score is None or weighted_gini < best_score:
                best_score = weighted_gini
                best_choice = (f, th, weighted_gini)
    return best_choice


# Random Forest-এর ম্যাজিক: প্রতি Split-এ সব 3টি নয়, র‍্যান্ডমলি max_features=2টি Feature বাছাই!
random.seed(7)
all_features = [0, 1, 2]
chosen_counts = {0: 0, 1: 0, 2: 0}

for tree_id in range(6):
    # Without replacement 2টি Feature বেছে নেওয়া
    subset = random.sample(all_features, 2)
    f, th, g = best_split_on_subset(X, y, subset)
    chosen_counts[f] += 1
    print(f"Tree {tree_id + 1}: allowed={subset} -> split feature_{f} <= {th:.1f} (Gini={g:.3f})")

print("Root feature diversity across 6 trees:", chosen_counts)

import math


def binary_alpha(error):
    return 0.5 * math.log((1.0 - error) / error)


def samme_alpha(error, num_classes):
    # K-class SAMME সূত্র: log((1 - err) / err) + log(K - 1)
    return math.log((1.0 - error) / error) + math.log(num_classes - 1)


# দেখুন K=3 ক্লাসে error=0.55 হলেও (Random guessing = 0.667-এর চেয়ে ভালো!):
err = 0.55
print(f"Binary alpha at err={err}:      {binary_alpha(err):.4f}  (নেগেটিভ! থেমে যেত)")
print(f"SAMME (K=3) alpha at err={err}: {samme_alpha(err, 3):.4f}  (পজিটিভ! শেখা চালু)")

# K=3 ক্লাসে বিভিন্ন error-এ SAMME alpha কেমন বদলায়:
for e in [0.10, 0.30, 0.50, 0.60]:
    a = samme_alpha(e, 3)
    print(f"K=3, error={e:.2f} -> alpha_SAMME = {a:.4f}")

X = [1, 2, 3, 4, 5, 6]
y = [3.0, 5.0, 7.0, 15.0, 18.0, 20.0]

learning_rate = 0.3
num_rounds = 5


def mean_value(values):
    total = 0.0
    for v in values:
        total += v
    return total / len(values)


def compute_mse(y_true, y_pred):
    total_sq_error = 0.0
    for i in range(len(y_true)):
        diff = y_true[i] - y_pred[i]
        total_sq_error += diff * diff
    return total_sq_error / len(y_true)


def fit_residual_stump(X_data, residuals):
    unique_x = sorted(set(X_data))
    best_sse = None
    best_stump = None

    for k in range(len(unique_x) - 1):
        threshold = (unique_x[k] + unique_x[k + 1]) / 2.0
        left_vals = []
        right_vals = []

        for i in range(len(X_data)):
            if X_data[i] <= threshold:
                left_vals.append(residuals[i])
            else:
                right_vals.append(residuals[i])

        if len(left_vals) == 0 or len(right_vals) == 0:
            continue

        left_mean = mean_value(left_vals)
        right_mean = mean_value(right_vals)

        sse = 0.0
        for v in left_vals:
            diff = v - left_mean
            sse += diff * diff
        for v in right_vals:
            diff = v - right_mean
            sse += diff * diff

        if best_sse is None or sse < best_sse:
            best_sse = sse
            best_stump = {
                "threshold": threshold,
                "left_val": left_mean,
                "right_val": right_mean,
            }

    return best_stump


def predict_stump(stump, x_val):
    if x_val <= stump["threshold"]:
        return stump["left_val"]
    return stump["right_val"]


# --- Training Loop ---
base_prediction = mean_value(y)
predictions = []
for i in range(len(y)):
    predictions.append(base_prediction)

trees = []
for round_num in range(1, num_rounds + 1):
    residuals = []
    for i in range(len(y)):
        r_i = y[i] - predictions[i]  # Squared loss negative gradient
        residuals.append(r_i)

    stump = fit_residual_stump(X, residuals)
    trees.append(stump)

    for i in range(len(y)):
        correction = predict_stump(stump, X[i])
        predictions[i] += learning_rate * correction

    mse = compute_mse(y, predictions)
    print(
        f"Round {round_num}: split x<={stump['threshold']} | "
        f"L={stump['left_val']:.4f}, R={stump['right_val']:.4f} | "
        f"Train MSE={mse:.4f}"
    )

# --- Inference on New Data ---
X_new = [2.5, 4.5]
new_predictions = []
for x_val in X_new:
    pred = base_prediction
    for stump in trees:
        pred += learning_rate * predict_stump(stump, x_val)
    new_predictions.append(round(pred, 4))

print("New Predictions:", new_predictions)

def early_stopping_best_round(val_losses, patience=3, min_delta=1e-4):
    best_loss = None
    best_round = 0
    rounds_without_gain = 0

    for idx in range(len(val_losses)):
        current = val_losses[idx]
        if best_loss is None or current < best_loss - min_delta:
            best_loss = current
            best_round = idx + 1   # 1-based Round নম্বর
            rounds_without_gain = 0
        else:
            rounds_without_gain += 1
            if rounds_without_gain >= patience:
                return {
                    "stopped_at": idx + 1,
                    "best_round": best_round,
                    "best_val_loss": best_loss,
                }

    return {
        "stopped_at": len(val_losses),
        "best_round": best_round,
        "best_val_loss": best_loss,
    }


# কাল্পনিক কিন্তু বাস্তবসম্মত Validation Loss (Round 5-এর পর Overfitting শুরু!)
val_curve = [0.68, 0.54, 0.45, 0.40, 0.38, 0.39, 0.41, 0.44, 0.49]
result = early_stopping_best_round(val_curve, patience=3)

print("Stopped training at Round:", result["stopped_at"])
print("Best restored Round:      ", result["best_round"])
print("Best Validation Loss:     ", result["best_val_loss"])

