def oob_average(p, in_bag):
    if len(p) != len(in_bag):
        raise ValueError("Alignment")
    eligible = [v for v, inside in zip(p, in_bag) if not inside]
    return None if not eligible else sum(eligible) / len(eligible)


assert oob_average([0.2], [True]) is None
answer = oob_average([0.2, 0.9, 0.4], [True, False, False])
print(answer)

import math


def weight(G, H, lam):
    if (
        not all(math.isfinite(x) for x in (G, H, lam))
        or H < 0
        or lam < 0
        or H + lam <= 0
    ):
        raise ValueError("Curvature contract")
    return -G / (H + lam)


answer = weight(-3, 2, 1)
assert -3 + (2 + 1) * answer == 0
print(answer)
